package com.smartjobtracker.repository; import com.smartjobtracker.model.IngestedEmail; import org.springframework.data.jpa.repository.JpaRepository; import java.util.List; import java.util.Optional; public interface IngestedEmailRepository extends JpaRepository<IngestedEmail,Long>{Optional<IngestedEmail> findByUserIdAndGmailMessageId(Long userId,String messageId); Optional<IngestedEmail> findByIdAndUserId(Long id,Long userId); List<IngestedEmail> findByUserIdAndReviewStatusOrderByReceivedAtDesc(Long userId,String reviewStatus);}